mapper.select:
SELECT p.id, p.category_id, sc.name AS category_name, p.title, p.author_id, u.username AS author_name, p.is_public, p.view_count, p.is_pinned, p.created_at, p.updated_at, (SELECT COUNT(*) FROM study_likes WHERE post_id = p.id) AS like_count, (SELECT COUNT(*) FROM study_comments WHERE post_id = p.id) AS comment_count FROM study_posts p INNER JOIN study_categories sc ON p.category_id = sc.id INNER JOIN users u ON p.author_id = u.id WHERE p.category_id = #{categoryId} AND (
p.is_public = false AND p.author_id = #{currentUserId}
p.is_public = true OR p.author_id = #{currentUserId}
)
AND (p.title ILIKE CONCAT('%', #{keyword}, '%') OR p.content ILIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.is_pinned DESC, p.created_at DESC
